-- The derived KPI fields, as views.
-- GENERATED by scripts/sql-derived.mjs — do not edit by hand.
-- Views, not stored columns: a stored value does not recompute when a
-- GRANDCHILD changes, and Airtable's rollups do. See the file header.

DROP VIEW IF EXISTS "v_contacts";
CREATE VIEW "v_contacts" AS
WITH ev AS (
  SELECT contact_id,
         MAX("has_any_signal") AS has_signal,
         MAX("is_complete")    AS has_complete_row
  FROM "event_rows" WHERE contact_id IS NOT NULL GROUP BY contact_id
),
cl AS (
  SELECT contact_id,
         COUNT("called_at")        AS call_count,
         MAX("called_at")          AS last_call_at,
         MIN("called_at")          AS first_call_at,
         SUM("measured_seconds")   AS talk_seconds,
         COUNT(*)                  AS measured_calls
  FROM "call_log" WHERE contact_id IS NOT NULL GROUP BY contact_id
),
st AS (
  SELECT contact_id,
         MAX("changed_at") AS last_stage_change_at,
         MIN("changed_at") AS first_stage_change_at
  FROM "stage_transitions" WHERE contact_id IS NOT NULL GROUP BY contact_id
)
SELECT
  c."id",
  c."airtable_id",
  c."kylas_contact_id",
  c."name",
  c."company_id",
  -- the company's Kylas id on the contact, so contacts can be filtered by
  -- company without a join at the call site
  co."kylas_company_id"                              AS "company_kylas_id",
  COALESCE(ev.has_signal, 0)                         AS "has_signal",
  COALESCE(ev.has_complete_row, 0)                   AS "has_complete_row",
  COALESCE(cl.call_count, 0)                         AS "call_count",
  cl.last_call_at                                    AS "last_call_at",
  cl.first_call_at                                   AS "first_call_at",
  COALESCE(cl.talk_seconds, 0)                       AS "talk_seconds",
  COALESCE(cl.measured_calls, 0)                     AS "measured_calls",
  -- across ALL calls; an estimated duration counts as 0, so read it beside
  -- talk_seconds rather than on its own
  CASE WHEN COALESCE(cl.call_count, 0) > 0
       THEN CAST(ROUND(COALESCE(cl.talk_seconds, 0) * 1.0 / cl.call_count) AS INTEGER)
       ELSE 0 END                                    AS "avg_call_seconds",
  st.last_stage_change_at                            AS "last_stage_change_at",
  st.first_stage_change_at                           AS "first_stage_change_at",
  CASE WHEN COALESCE(ev.has_signal, 0) = 1 THEN 1 ELSE 0 END        AS "is_right_poc",
  CASE WHEN COALESCE(ev.has_signal, 0) = 1 THEN c."name" ELSE '' END AS "right_poc_name",
  CASE WHEN COALESCE(ev.has_complete_row, 0) = 1 THEN 1 ELSE 0 END  AS "is_discovery",
  CASE WHEN COALESCE(ev.has_complete_row, 0) = 1 THEN c."name" ELSE '' END AS "discovery_name",
  CASE WHEN COALESCE(c."kpi_rank", 0) = 2 THEN '02 · POC - Organization - Changed' WHEN COALESCE(c."kpi_rank", 0) = 3 THEN '03 · Not a Decision Maker (NDM)' WHEN COALESCE(c."kpi_rank", 0) = 4 THEN '04 · Invalid Contact' WHEN COALESCE(c."kpi_rank", 0) = 5 THEN '05 · Disqualified - Wrong POC' WHEN COALESCE(c."kpi_rank", 0) = 6 THEN '06 · CNC (Could Not Connect) - 1' WHEN COALESCE(c."kpi_rank", 0) = 7 THEN '07 · CNC (Could Not Connect) - 2' WHEN COALESCE(c."kpi_rank", 0) = 8 THEN '08 · CNC (Could Not Connect) - 3' WHEN COALESCE(c."kpi_rank", 0) = 9 THEN '09 · Connect Later' WHEN COALESCE(c."kpi_rank", 0) = 10 THEN '10 · Not Interested' WHEN COALESCE(c."kpi_rank", 0) = 11 THEN '11 · Offsite Done (Late Reachout)' WHEN COALESCE(c."kpi_rank", 0) = 12 THEN '12 · Offsite Delayed' WHEN COALESCE(c."kpi_rank", 0) = 13 THEN '13 · Activation' WHEN COALESCE(c."kpi_rank", 0) = 14 THEN '14 · MQL (Marketing Qualified Lead)' WHEN COALESCE(c."kpi_rank", 0) = 15 THEN '15 · Followup - CNC' WHEN COALESCE(c."kpi_rank", 0) = 16 THEN '16 · Follow-up (3)' WHEN COALESCE(c."kpi_rank", 0) = 17 THEN '17 · Follow-up (2)' WHEN COALESCE(c."kpi_rank", 0) = 18 THEN '18 · Follow-up (1)' WHEN COALESCE(c."kpi_rank", 0) = 19 THEN '19 · Discovery Call Booked' WHEN COALESCE(c."kpi_rank", 0) = 20 THEN '20 · Discovery Call No-Show' WHEN COALESCE(c."kpi_rank", 0) = 21 THEN '21 · Closing Loops - Low Value' WHEN COALESCE(c."kpi_rank", 0) = 22 THEN '22 · Discovery Call Done - Awaiting Client Inputs' WHEN COALESCE(c."kpi_rank", 0) = 23 THEN '23 · Active Requirement Call Booked' WHEN COALESCE(c."kpi_rank", 0) = 24 THEN '24 · Active Requirement Call No-Show' WHEN COALESCE(c."kpi_rank", 0) = 25 THEN '25 · Active Requirement Call Done – Awaiting Client Inputs' WHEN COALESCE(c."kpi_rank", 0) = 26 THEN '26 · SQL (Sales Qualified Lead)' ELSE '01 · LinkedIn Outreach Initiated' END         AS "kpi_stage",
  -- rank in the high digits, the moment it was reached in the low ones, so a
  -- single MAX at company level gives the best rung and, among ties, the most
  -- recent. The same packing Airtable's formula does.
  CASE WHEN c."kpi_rank_at" IS NOT NULL
       THEN COALESCE(c."kpi_rank", 0) * 10000000000 + CAST(strftime('%s', c."kpi_rank_at") AS INTEGER)
       ELSE COALESCE(c."kpi_rank", 0) * 10000000000 END AS "kpi_score"
FROM "contacts" c
LEFT JOIN "companies" co ON co."id" = c."company_id"
LEFT JOIN ev ON ev.contact_id = c."id"
LEFT JOIN cl ON cl.contact_id = c."id"
LEFT JOIN st ON st.contact_id = c."id";

DROP VIEW IF EXISTS "v_companies";
CREATE VIEW "v_companies" AS
WITH ct AS (
  SELECT v."company_id"                                        AS company_id,
         MAX(v."last_call_at")                                 AS last_call_at,
         MIN(v."first_call_at")                                AS first_call_at,
         -- MIN, so a company counts from the period its FIRST contact was
         -- worked rather than its latest one
         MIN(c."first_worked_at")                              AS first_worked_at,
         MIN(c."first_picked_at")                              AS first_picked_at,
         SUM(v."call_count")                                   AS call_count,
         SUM(v."talk_seconds")                                 AS talk_seconds,
         MAX(c."ever_picked")                                  AS ever_picked,
         MAX(v."kpi_score")                                    AS kpi_score,
         COUNT(v."name")                                       AS contact_count,
         group_concat(NULLIF(v."right_poc_name", ''), ', ')    AS right_poc_contacts,
         group_concat(NULLIF(v."discovery_name", ''), ', ')    AS discovery_contacts
  FROM "v_contacts" v
  JOIN "contacts" c ON c."id" = v."id"
  WHERE v."company_id" IS NOT NULL
  GROUP BY v."company_id"
)
SELECT
  co."id",
  co."airtable_id",
  co."kylas_company_id",
  co."name",
  ct.last_call_at                             AS "last_call_at",
  ct.first_call_at                            AS "first_call_at",
  ct.first_worked_at                          AS "first_worked_at",
  ct.first_picked_at                          AS "first_picked_at",
  COALESCE(ct.call_count, 0)                  AS "call_count",
  COALESCE(ct.talk_seconds, 0)                AS "talk_seconds",
  COALESCE(ct.ever_picked, 0)                 AS "ever_picked",
  COALESCE(ct.kpi_score, 0)                   AS "kpi_score",
  COALESCE(ct.contact_count, 0)               AS "contact_count",
  COALESCE(ct.right_poc_contacts, '')         AS "right_poc_contacts",
  COALESCE(ct.discovery_contacts, '')         AS "discovery_contacts",
  CASE WHEN ct.last_call_at IS NOT NULL THEN 1 ELSE 0 END           AS "reached",
  CASE WHEN COALESCE(ct.ever_picked, 0) = 1 THEN 1 ELSE 0 END       AS "phone_picked",
  CASE WHEN COALESCE(ct.right_poc_contacts, '') <> '' THEN 1 ELSE 0 END AS "right_poc",
  -- a complete row has all three filled, so it also has any one: Discovery is
  -- always a subset of Right POC and the funnel reads straight down
  CASE WHEN COALESCE(ct.discovery_contacts, '') <> '' THEN 1 ELSE 0 END AS "successful_discovery",
  CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER)        AS "kpi_rank",
  -- the three stage milestones are floors on the ladder. KPI Rank only ever
  -- rises, so "ever reached it" needs no history — the rank IS the high-water
  -- mark, and Booked counts a company whose call was booked and then no-showed
  CASE WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) >= 23 THEN 1 ELSE 0 END AS "sql_meeting_booked",
  CASE WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) >= 25 THEN 1 ELSE 0 END AS "sql_meeting_done",
  CASE WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) >= 26 THEN 1 ELSE 0 END AS "sql",
  CASE WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 2 THEN '02 · POC - Organization - Changed' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 3 THEN '03 · Not a Decision Maker (NDM)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 4 THEN '04 · Invalid Contact' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 5 THEN '05 · Disqualified - Wrong POC' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 6 THEN '06 · CNC (Could Not Connect) - 1' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 7 THEN '07 · CNC (Could Not Connect) - 2' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 8 THEN '08 · CNC (Could Not Connect) - 3' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 9 THEN '09 · Connect Later' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 10 THEN '10 · Not Interested' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 11 THEN '11 · Offsite Done (Late Reachout)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 12 THEN '12 · Offsite Delayed' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 13 THEN '13 · Activation' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 14 THEN '14 · MQL (Marketing Qualified Lead)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 15 THEN '15 · Followup - CNC' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 16 THEN '16 · Follow-up (3)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 17 THEN '17 · Follow-up (2)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 18 THEN '18 · Follow-up (1)' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 19 THEN '19 · Discovery Call Booked' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 20 THEN '20 · Discovery Call No-Show' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 21 THEN '21 · Closing Loops - Low Value' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 22 THEN '22 · Discovery Call Done - Awaiting Client Inputs' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 23 THEN '23 · Active Requirement Call Booked' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 24 THEN '24 · Active Requirement Call No-Show' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 25 THEN '25 · Active Requirement Call Done – Awaiting Client Inputs' WHEN CAST(COALESCE(ct.kpi_score, 0) / 10000000000 AS INTEGER) = 26 THEN '26 · SQL (Sales Qualified Lead)' ELSE '01 · LinkedIn Outreach Initiated' END AS "kpi_stage",
  -- when it last moved up a rung: the low half of the score, read back out
  CASE WHEN COALESCE(ct.kpi_score, 0) > 0
       THEN strftime('%Y-%m-%dT%H:%M:%SZ', COALESCE(ct.kpi_score, 0) % 10000000000, 'unixepoch')
       ELSE NULL END                          AS "kpi_stage_at"
FROM "companies" co
LEFT JOIN ct ON ct.company_id = co."id";
